  @Test
  @DisplayName("dispatch skips message when no SMTP config is available")
  void dispatch_skipsWhenNoSmtpConfig() {
    Message msg = pendingMessage("uid-1", 0, Optional.empty(), Optional.empty(), "<p>Hi</p>");
    when(messageReader.list(any())).thenReturn(List.of(msg));
    when(smtpConfigReader.find(any())).thenReturn(Optional.empty());

    service.dispatch();

    verify(mailSender, never()).send(any(), any(OutboundMail.class));
  }

  @Test
  @DisplayName("dispatch uses tenant-specific SMTP config when found")
  void dispatch_usesTenantSmtpConfigFirst() {
    Message msg = pendingMessage("uid-1", 0, Optional.of("T1"), Optional.empty(),
        "{\"subject\":\"S\",\"html\":\"<p>H</p>\",\"text\":null}");
    SmtpOutboundConfig tenantSmtp = smtpConfig(3, false);
    when(messageReader.list(any())).thenReturn(List.of(msg));
    // tenant-specific lookup returns config
    when(smtpConfigReader.find(argThat(f -> !f.getGlobalOnly().orElse(false))))
        .thenReturn(Optional.of(tenantSmtp));
    Message deleted = mock(Message.class);
    when(msg.delete()).thenReturn(deleted);

    service.dispatch();

    verify(mailSender).send(any(), any(OutboundMail.class));
    // global lookup should NOT be called since tenant config was found
    verify(smtpConfigReader, never()).find(argThat(f -> f.getGlobalOnly().orElse(false)));
  }

  @Test
  @DisplayName("dispatch falls back to global SMTP config when tenant config is absent")
  void dispatch_fallsBackToGlobalSmtpConfig() {
    Message msg = pendingMessage("uid-1", 0, Optional.of("T1"), Optional.empty(),
        "{\"subject\":\"S\",\"html\":\"<p>H</p>\",\"text\":null}");
    SmtpOutboundConfig globalSmtp = smtpConfig(3, false);
    when(messageReader.list(any())).thenReturn(List.of(msg));
    when(smtpConfigReader.find(argThat(f -> !f.getGlobalOnly().orElse(false))))
        .thenReturn(Optional.empty());
    when(smtpConfigReader.find(argThat(f -> f.getGlobalOnly().orElse(false))))
        .thenReturn(Optional.of(globalSmtp));
    Message deleted = mock(Message.class);
    when(msg.delete()).thenReturn(deleted);

    service.dispatch();

    verify(mailSender).send(any(), any(OutboundMail.class));
  }

