  @Test
  @DisplayName("dispatch passes parsed subject and html body from JSON content to mail sender")
  void dispatch_parsesJsonContent() {
    Message msg = pendingMessage("uid-1", 0, Optional.empty(), Optional.empty(),
        "{\"subject\":\"Test Subject\",\"html\":\"<p>Hello</p>\",\"text\":\"Hello\"}");
    SmtpOutboundConfig smtp = smtpConfig(3, false);
    when(messageReader.list(any())).thenReturn(List.of(msg));
    when(smtpConfigReader.find(any())).thenReturn(Optional.of(smtp));
    Message deleted = mock(Message.class);
    when(msg.delete()).thenReturn(deleted);

    service.dispatch();

    ArgumentCaptor<OutboundMail> mailCaptor = ArgumentCaptor.forClass(OutboundMail.class);
    verify(mailSender).send(any(), mailCaptor.capture());
    OutboundMail sent = mailCaptor.getValue();
    org.junit.jupiter.api.Assertions.assertEquals("Test Subject", sent.getSubject());
    org.junit.jupiter.api.Assertions.assertEquals("<p>Hello</p>", sent.getHtmlContent());
    org.junit.jupiter.api.Assertions.assertEquals("Hello", sent.getTextContent());
  }

