  // ---------------------------------------------------------------------------
  // send failure / retry
  // ---------------------------------------------------------------------------

  @Test
  @DisplayName("dispatch increments retries when send throws an exception")
  void dispatch_incrementsRetriesOnSendFailure() {
    Message msg = pendingMessage("uid-1", 1, Optional.empty(), Optional.empty(),
        "{\"subject\":\"S\",\"html\":\"<p>H</p>\",\"text\":null}");
    SmtpOutboundConfig smtp = smtpConfig(3, false);
    when(messageReader.list(any())).thenReturn(List.of(msg));
    when(smtpConfigReader.find(any())).thenReturn(Optional.of(smtp));
    doThrow(new RuntimeException("SMTP error")).when(mailSender).send(any(), any());
    Message updated = mock(Message.class);
    when(msg.update(any(MessageChangeSet.class))).thenReturn(updated);

    service.dispatch();

    verify(messageWriter).update(msg, updated);
    verify(messageWriter, never()).delete(any());
  }

  @Test
  @DisplayName("dispatch does not rethrow when retry increment itself fails")
  void dispatch_doesNotRethrowWhenIncrementRetriesFails() {
    Message msg = pendingMessage("uid-1", 0, Optional.empty(), Optional.empty(),
        "{\"subject\":\"S\",\"html\":\"<p>H</p>\",\"text\":null}");
    SmtpOutboundConfig smtp = smtpConfig(3, false);
    when(messageReader.list(any())).thenReturn(List.of(msg));
    when(smtpConfigReader.find(any())).thenReturn(Optional.of(smtp));
    doThrow(new RuntimeException("SMTP error")).when(mailSender).send(any(), any());
    when(msg.update(any())).thenThrow(new RuntimeException("DB error"));

    // Should not propagate either exception
    service.dispatch();
  }

