  /**
   * Creates a mock {@link Message} pre-configured with the given attributes.
   */
  private Message pendingMessage(String uid, int retries, Optional<String> tenantUid,
      Optional<OffsetDateTime> sendAt, String content) {
    Message msg = mock(Message.class);
    when(msg.getUid()).thenReturn(uid);
    when(msg.getRetries()).thenReturn(retries);
    when(msg.getTenantUid()).thenReturn(tenantUid);
    when(msg.getSendAt()).thenReturn(sendAt);
    when(msg.getContent()).thenReturn(content);
    when(msg.getTarget()).thenReturn("recipient@example.com");
    return msg;
  }

  /**
   * Creates a mock {@link SmtpOutboundConfig} pre-configured with the given attributes.
   */
  private SmtpOutboundConfig smtpConfig(int maxRetries, boolean useTls) {
    SmtpOutboundConfig smtp = mock(SmtpOutboundConfig.class);
    when(smtp.getMaxRetries()).thenReturn(maxRetries);
    when(smtp.isUseTls()).thenReturn(useTls);
    when(smtp.getHost()).thenReturn("smtp.example.com");
    when(smtp.getLogin()).thenReturn("login");
    when(smtp.getPasswordPlain(any())).thenReturn("secret");
    when(smtp.getTimeout()).thenReturn(30);
    when(smtp.getSenderEmail()).thenReturn("noreply@example.com");
    when(smtp.getSenderName()).thenReturn(Optional.of("Sender"));
    return smtp;
  }
